var distance = function(nums) {
    const n = nums.length;
    const map = new Map();

    for (let i = 0; i < n; i++) {
        if (!map.has(nums[i])) {
            map.set(nums[i], []);
        }
        map.get(nums[i]).push(i);
    }

    const res = Array(n);

    for (let i = 0; i < n; i++) {
        const arr = map.get(nums[i]);

        let sum = 0;

        for (const index of arr) {
            if (index === i) continue;

            sum += Math.abs(i - index);
        }

        res[i] = sum;
    }

    return res;
};

