var distance = function(nums) {
    const n = nums.length;
    const map = new Map();
    const dp = new Array(n).fill(0);

    for (let i = 0; i < n; i++) {
        if (!map.has(nums[i])) {
            map.set(nums[i], []);
        }
        map.get(nums[i]).push(i);
    }

    const res = Array(n).fill(0);

    for (const group of map.values()) {
        let total = 0;
        for (const idx of group) {
            total += idx;
        }

        const len = group.length;
        let prefixTotal = 0;

        for (let i = 0; i < len; i++) {
            const index = group[i];
            res[index] = total - 2 * prefixTotal + index * (2 * i - len);
            prefixTotal += index;
        }
    }

    return res;
};
